            throw new Error("Native callbacks are disabled; use managed MCP tools.");
    }
    async permission(params) {
        if (this.signal?.aborted)
            return { outcome: { outcome: "cancelled" } };
        const kind = params.toolCall.kind;
        // Only this session's managed 'lemmaduck' server receives this exception. The
        // parent MCP server independently checks arguments/mode and asks for shell
        // approval before execution; no duplicate native confirmation is needed.
        const meta = params.toolCall._meta;
        const mcp = meta?.mcp;
        const managed = this.options.mcpServers?.some(server => server.name === "lemmaduck") && ((mcp?.server === "lemmaduck" && /^(inspect_research|compare_research_actions|record_research|run_research_experiment|read_task_artifact|propose_checkpoint|inspect_vcs|list_connections|list_connection_tools|call_connection|read|grep|find|ls|write|edit|bash)$/.test(mcp.tool || "")) ||
            (kind === "other" && /^(inspect_research|compare_research_actions|record_research|run_research_experiment|read_task_artifact|propose_checkpoint|inspect_vcs|list_connections|list_connection_tools|call_connection|read|grep|find|ls|write|edit|bash) \(lemmaduck MCP Server\)$/.test(params.toolCall.title || "")));
        const denied = this.options.review && !managed && !["read", "search", "think"].includes(kind || "");
        const detail = JSON.stringify(params.toolCall.rawInput ?? { locations: params.toolCall.locations, content: params.toolCall.content });
        const accepted = !denied && (managed || (!this.options.managedToolsOnly && await this.options.approve(params.toolCall.title || "Gemini tool", detail, this.signal)));
        if (!accepted || this.signal?.aborted)
            return { outcome: { outcome: "cancelled" } };
        const option = params.options.find(item => item.kind === "allow_once");
        return option ? { outcome: { outcome: "selected", optionId: option.optionId } } : { outcome: { outcome: "cancelled" } };
    }
    client() {
        return {
            requestPermission: params => this.permission(params),
            sessionUpdate: params => this.options.update(params),
